107	SensorManager::sensorQueueChanged(void)
108	{
109	  SoSensorManager * sensormanager = SoDB::getSensorManager();
110	  assert(sensormanager);
111	
112	  SbTime interval;
113	  if (sensormanager->isTimerSensorPending(interval)) {
114	    interval -= SbTime::getTimeOfDay();
115	    if (interval.getValue() < this->timerEpsilon) {
116	      interval.setValue(this->timerEpsilon);
117	    }
118	    if (!this->timerqueuetimer->isActive()) {
119	      this->timerqueuetimer->start(interval.getMsecValue());
120	    } else {
121	      this->timerqueuetimer->setInterval(interval.getMsecValue());
122	    }
123	  } else if (this->timerqueuetimer->isActive()) {
124	    this->timerqueuetimer->stop();
125	  }
126	
127	  if (sensormanager->isDelaySensorPending()) {
128	    this->idletimer->start(0);
129	
130	    if (!this->delaytimer->isActive()) {
131	      SbTime time = SoDB::getDelaySensorTimeout();
132	      if (time != SbTime::zero()) {
133	        this->delaytimer->start(time.getMsecValue());
134	      }
135	    }
136	  } else {
137	    if (this->idletimer->isActive()) {
138	      this->idletimer->stop();
139	    }
140	    if (this->delaytimer->isActive()) {
141	      this->delaytimer->stop();
142	    }
143	  }
144	}
