128: QuarterWidgetP::findCacheContext(QuarterWidget * widget, const QUARTER_GL_WIDGET * sharewidget)
129: {
130:   if (cachecontext_list == NULL) {
131:     // FIXME: static memory leak
132:     cachecontext_list = new SbList <QuarterWidgetP_cachecontext*>;
133:   }
134:   for (int i = 0; i < cachecontext_list->getLength(); i++) {
135:     QuarterWidgetP_cachecontext * cachecontext = (*cachecontext_list)[i];
136: 
137:     for (int j = 0; j < cachecontext->widgetlist.getLength(); j++) {
138:       if (cachecontext->widgetlist[j] == sharewidget) {
139:         cachecontext->widgetlist.append((const QUARTER_GL_WIDGET*) widget);
140:         return cachecontext;
141:       }
142:     }
143:   }
144:   QuarterWidgetP_cachecontext * cachecontext = new QuarterWidgetP_cachecontext;
145:   cachecontext->id = SoGLCacheContextElement::getUniqueCacheContext();
146:   cachecontext->widgetlist.append((const QUARTER_GL_WIDGET*) widget);
147:   cachecontext_list->append(cachecontext);
148: 
149:   return cachecontext;
