152: void
153: QuarterWidgetP::removeFromCacheContext(QuarterWidgetP_cachecontext * context, const QUARTER_GL_WIDGET * widget)
154: {
155:   context->widgetlist.removeItem((const QUARTER_GL_WIDGET*) widget);
156: 
157:   if (context->widgetlist.getLength() == 0) { // last context in this share group?
158:     assert(cachecontext_list);
159: 
160:     for (int i = 0; i < cachecontext_list->getLength(); i++) {
161:       if ((*cachecontext_list)[i] == context) {
162:         QUARTER_GL_CONTEXT* glcontext = widget->context();
163:         if (glcontext) {
164:           // set the context while calling destructingContext() (might trigger OpenGL calls)
165:           if (glcontext->isValid()) {
166:             const_cast<QUARTER_GL_WIDGET*> (widget)->makeCurrent();
167:           }
168:           // fetch the cc_glglue context instance as a workaround for a bug fixed in Coin r12818
169:           (void) cc_glglue_instance(context->id);
170:         }
171:         cachecontext_list->removeFast(i);
172:         SoContextHandler::destructingContext(context->id);
173:         if (glcontext) {
174:           if (glcontext->isValid()) {
175:             const_cast<QUARTER_GL_WIDGET*> (widget)->doneCurrent();
176:           }
177:         }
178:         delete context;
179:         return;
180:       }
181:     }
