491: void
492: QuarterWidget::setSceneGraph(SoNode * node)
493: {
494:   if (node == PRIVATE(this)->scene) {
495:     return;
496:   }
497: 
498:   if (PRIVATE(this)->scene) {
499:     PRIVATE(this)->scene->unref();
500:     PRIVATE(this)->scene = NULL;
501:   }
502: 
503:   SoCamera * camera = NULL;
504:   SoSeparator * superscene = NULL;
505:   bool viewall = false;
506: 
507:   if (node) {
508:     PRIVATE(this)->scene = node;
509:     PRIVATE(this)->scene->ref();
510: 
511:     superscene = new SoSeparator;
512:     superscene->addChild(PRIVATE(this)->headlight);
513: 
514:     // if the scene does not contain a camera, add one
515:     if (!(camera = PRIVATE(this)->searchForCamera(node))) {
516:       camera = new SoPerspectiveCamera;
517:       superscene->addChild(camera);
518:       viewall = true;
519:     }
520: 
521:     superscene->addChild(node);
522:   }
523: 
524:   PRIVATE(this)->soeventmanager->setCamera(camera);
525:   PRIVATE(this)->sorendermanager->setCamera(camera);
526:   PRIVATE(this)->soeventmanager->setSceneGraph(superscene);
527:   PRIVATE(this)->sorendermanager->setSceneGraph(superscene);
528: 
529:   if (viewall) { this->viewAll(); }
530:   if (superscene) { superscene->touch(); }
531: }
