732: /*!
733:   Overridden from QGLWidget to render the scene graph.
734: */
735: void
736: QuarterWidget::paintGL(void)
737: {
738: #if (QT_VERSION >= 0x050600)
739:   if(updateDevicePixelRatio()) {
740:     qreal dev_pix_ratio = devicePixelRatio();
741:     int width = (int)(dev_pix_ratio * this->width());
742:     int height = (int)(dev_pix_ratio * this->height());
743:     SbViewportRegion vp(width, height);
744:     PRIVATE(this)->sorendermanager->setViewportRegion(vp);
745:     PRIVATE(this)->soeventmanager->setViewportRegion(vp);
746:   }
747: #endif
748: 
749:   assert(this->isValid() && "No valid GL context found!");
750:   // We might have to process the delay queue here since we don't know
751:   // if paintGL() is called from Qt, and we might have some sensors
752:   // waiting to trigger (the redraw sensor has a lower priority than a
753:   // normal field sensor to guarantee that your sensor is processed
754:   // before the next redraw). Disable autorendering while we do this
755:   // to avoid recursive redraws.
756: 
757:   // We set the PRIVATE(this)->processdelayqueue = false in redraw()
758:   // to avoid processing the delay queue when paintGL() is triggered
759:   // by us, and we don't want to process the delay queue in those
760:   // cases
761: 
762:   PRIVATE(this)->autoredrawenabled = false;
763:   if (PRIVATE(this)->processdelayqueue && SoDB::getSensorManager()->isDelaySensorPending()) {
764:     // processing the sensors might trigger a redraw in another
765:     // context. Release this context temporarily
766:     this->doneCurrent();
767:     SoDB::getSensorManager()->processDelayQueue(FALSE);
768:     this->makeCurrent();
769:   }
770:   assert(this->isValid() && "No valid GL context found!");
771:   // we need to render immediately here, and not do scheduleRedraw()
772:   // since Qt will swap the GL buffers after calling paintGL().
773:   this->actualRedraw();
774:   PRIVATE(this)->autoredrawenabled = true;
775:   
776:   // process the delay queue the next time we enter this function,
777:   // unless we get here after a call to redraw().
778:   PRIVATE(this)->processdelayqueue = true;
779: }
